def language():
    return st.session_state.get('ui_language', st.query_params.get('lang', 'en'))


def tr(message, _language=None, **values):
    english = {'missed_mate': 'Missed mate', 'allowed_mate': 'Allowed mate', 'evaluation_drop': 'Evaluation drop'}
    text = ZH.get(message, message) if (_language or language()) == 'zh' else english.get(message, message)
    return text.format(**values) if values else text


def error_text(error):
    text = str(error)
    if text.startswith('Invalid PGN: '):
        return tr('Invalid PGN: {error}', error=text[len('Invalid PGN: '):])
    return tr(text)


def job_message(message):
    match = re.fullmatch(r'Added (\d+) puzzles\. (?:Refresh your library to review them\.|Your library is up to date\.)', message)
    return tr('Added {count} puzzles. Your library is up to date.', count=match[1]) if match else tr(message)


def language_selector():
    if 'ui_language' not in st.session_state:
        requested = st.query_params.get('lang', 'en')
        st.session_state.ui_language = requested if requested in ('en', 'zh') else 'en'
    st.html('''<style>
    [data-testid="stToolbarActions"]{anchor-name:--chess-toolbar-actions;padding-inline-start:6rem}
    .st-key-language_toggle{position:fixed;top:3.75rem;right:0.75rem;width:2.5rem;z-index:1000002}
    .st-key-language_toggle button{width:2.5rem;height:2.5rem;padding:0;border-radius:0.5rem}
    @supports(position-anchor:--chess-toolbar-actions){
      .st-key-language_toggle{position-anchor:--chess-toolbar-actions;top:calc(anchor(center, 1.625rem) - 1.25rem);left:calc(anchor(left) + 0.25rem);right:auto}
    }
    </style>''')
    if st.button('', icon=':material/translate:', key='language_toggle', type='tertiary',
                 help='English / 中文'):
        st.session_state.ui_language = 'zh' if st.session_state.ui_language == 'en' else 'en'
        st.query_params['lang'] = st.session_state.ui_language
        # Resend canonical selections when radio display strings are translated.
        for key in ('analysis_source', 'analysis_loss_level'):
            if key in st.session_state:
                st.session_state[key] = st.session_state[key]
